from pathlib import Path
import base64,gzip,re
DATA = ''
html = gzip.decompress(base64.b64decode(DATA)).decode('utf-8')
Path('app/src/main/assets/index.html').write_text(html,encoding='utf-8')
b=Path('app/build.gradle').read_text(encoding='utf-8')
b=re.sub(r"versionCode\s+\d+","versionCode 3",b)
b=re.sub(r"versionName\s+'[^']+'","versionName '1.2-minimal-calendar'",b)
Path('app/build.gradle').write_text(b,encoding='utf-8')
print('Installed TM Mobile Shop Preview 6 source')
